let currentLang = (()=>{try{return localStorage.getItem('rmed_language')==='es'?'es':'pt'}catch(e){return 'pt'}})();
const originalTextNodes = new WeakMap();
const originalPlaceholders = new WeakMap();
const originalAriaLabels = new WeakMap();
function t(value){return currentLang==='es' ? (i18n.es[value] || value) : value;}
function dataset(pt,es){return currentLang==='es'?es:pt;}
function translateStatic(root=document.body){
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
 const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
 for(const n of nodes){
   if(!originalTextNodes.has(n)) originalTextNodes.set(n,n.nodeValue);
   const original=originalTextNodes.get(n), raw=original.trim();
   n.nodeValue=currentLang==='es' && raw && i18n.es[raw] ? original.replace(raw,i18n.es[raw]) : original;
 }
 root.querySelectorAll('[placeholder]').forEach(el=>{
   if(!originalPlaceholders.has(el)) originalPlaceholders.set(el,el.placeholder);
   const original=originalPlaceholders.get(el);
   el.placeholder=currentLang==='es'?(i18n.es[original]||original):original;
 });
 root.querySelectorAll('[aria-label]').forEach(el=>{
   if(!originalAriaLabels.has(el)) originalAriaLabels.set(el,el.getAttribute('aria-label'));
   const original=originalAriaLabels.get(el);
   el.setAttribute('aria-label',currentLang==='es'?(i18n.es[original]||original):original);
 });
 document.documentElement.lang=currentLang==='es'?'es':'pt-BR';
 document.title=currentLang==='es'?'RMed — Estudio y referencia médica':'RMed — Estudos e Referência Médica';
}
function setLanguage(lang){
 currentLang=lang==='es'?'es':'pt';
 try{localStorage.setItem('rmed_language',currentLang)}catch(e){}
 // Atualiza a interface sem recarregar: evita conflito com o cache do Safari.
 renderModules();renderDrugs();renderAbx();renderProtocols();renderQ();renderCases();renderClinic();renderMock();renderStats();
 translateStatic();
 const selector=document.getElementById('languageSelect');
 if(selector) selector.value=currentLang;
}

function renderModules(){let r=$('#moduleList'),activeModules=dataset(modules,modulesES);r.innerHTML=activeModules.map((m,i)=>`<div class="item"><div class="eyebrow">MÓDULO ${String(i+1).padStart(2,'0')}</div><h3>${m[0]}</h3><p>${m[1]}</p><button class="btn secondary" data-module="${i}">${state.done.includes(i)?t('Revisar conteúdo'):t('Abrir módulo')}</button></div>`).join('')}
$('#moduleList').addEventListener('click',e=>{let b=e.target.closest('[data-module]');if(!b)return;let i=+b.dataset.module,m=dataset(modules,modulesES)[i];$('#moduleBody').innerHTML=`<div class="card lesson"><div class="eyebrow">MÓDULO ${i+1} / 8</div><h2>${m[0]}</h2>${m[2]}<button class="btn" id="markDone">${state.done.includes(i)?t('Concluído ✓'):t('Marcar como estudado')}</button></div>`;$('#markDone').onclick=()=>{if(!state.done.includes(i))state.done.push(i);save();renderModules();$('#markDone').textContent=t('Concluído ✓')};$('#moduleBody').scrollIntoView({behavior:'smooth'})});
