function renderDrugs(){let q=$('#drugSearch').value.toLowerCase(),activeDrugs=dataset(drugs,drugsES);$('#drugList').innerHTML=activeDrugs.filter(d=>d.join(' ').toLowerCase().includes(q)).map(d=>`<div class="item"><span class="tag">${d[1]}</span><h3>${d[0]}</h3><p><b>${t('Mecanismo:')}</b> ${d[2]}</p><p><b>${t('Usos gerais:')}</b> ${d[3]}</p><p><b>${t('Riscos:')}</b> ${d[4]}</p><p><b>${t('Atenção:')}</b> ${d[5]}</p></div>`).join('')||'<p class="muted">Nenhum resultado.</p>'}
$('#drugSearch').addEventListener('input',renderDrugs);
