function renderClinic(){
 const lang=currentLang==='es'?'es':'pt', data=clinicData[lang], q=($('#clinicSearch')?.value||'').toLowerCase();
 const labels=lang==='es'?{source:'Fuente oficial',details:'Abrir ficha',type:'Tipo',alert:'Punto de seguridad'}:{source:'Fonte oficial',details:'Abrir ficha',type:'Tipo',alert:'Ponto de segurança'};
 $('#clinicContent').innerHTML=data.filter(x=>(x.title+' '+x.area+' '+x.summary+' '+x.sections.flat().join(' ')).toLowerCase().includes(q)).map((x,i)=>`
 <article class="item clinic-item"><div class="row" style="justify-content:space-between;gap:8px;flex-wrap:wrap"><span class="tag">${x.type}</span><span class="muted">${x.area}</span></div>
 <h3>${x.title}</h3><p>${x.summary}</p><details><summary>${labels.details}</summary>${x.sections.map(s=>`<div class="clinic-block"><h4>${s[0]}</h4><p>${s[1]}</p></div>`).join('')}<p class="muted"><b>${labels.source}:</b> <a href="${x.url}" target="_blank" rel="noopener">${x.source}</a></p></details></article>`).join('')||'<p class="muted">Nenhum resultado.</p>';
 $('#clinicTitle').textContent=lang==='es'?'Conductas y prescripciones':'Condutas e prescrições';
 $('#clinicIntro').textContent=lang==='es'?'Referencia educativa estructurada. Verifique contexto, contraindicaciones, protocolo local y presentación disponible antes de prescribir.':'Referência educacional estruturada. Confira contexto, contraindicações, protocolo local e apresentação disponível antes de prescrever.';
 $('#clinicSafety').innerHTML=lang==='es'?'<b>Seguridad:</b> las dosis son referencias para escenarios definidos, no prescripciones automáticas. Individualice por edad, peso, embarazo, función renal/hepática, alergias, interacciones y gravedad.':'<b>Segurança:</b> doses são referências para cenários definidos, não prescrições automáticas. Individualize por idade, peso, gestação, função renal/hepática, alergias, interações e gravidade.';
}
$('#clinicSearch').addEventListener('input',renderClinic);

