function renderCases(){let activeCases=dataset(cases,casesES);$('#caseMeta').textContent=(currentLang==='es'?'Banco de casos: ':'Banco de casos: ')+activeCases.length;$('#caseList').innerHTML=activeCases.map((c,i)=>`<div class="item"><span class="eyebrow">CASO ${i+1}</span><h3>${c[0]}</h3><p>${c[1]}</p>${c[2].map((o,j)=>`<button class="tile" style="min-height:45px;margin:5px 0" data-case="${i}" data-choice="${j}">${'ABCD'[j]}) ${o}</button>`).join('')}<div id="caseFb${i}" class="answer"></div></div>`).join('')}
$('#caseList').addEventListener('click',e=>{let b=e.target.closest('[data-case]');if(!b||b.disabled)return;let i=+b.dataset.case,j=+b.dataset.choice,c=dataset(cases,casesES)[i];$$(`[data-case="${i}"]`).forEach(x=>{x.disabled=true;if(+x.dataset.choice===c[3])x.classList.add('correct');if(+x.dataset.choice===j&&j!==c[3])x.classList.add('wrong')});let fb=$('#caseFb'+i);fb.style.display='block';fb.innerHTML=`<b>${j===c[3]?t('Boa análise.'):t('Revise o conceito.')}</b><p>${c[4]}</p>`});
function renderReview(){let due=state.cards.filter(c=>c.due<=Date.now());let r=$('#reviewBody');if(!due.length){r.innerHTML=currentLang==='es'?'No hay tarjetas pendientes. Los errores de las preguntas aparecerán aquí.':'Nenhum cartão pendente. Erros das questões aparecerão aqui.';return}let c=due[0];r.innerHTML=`<div class="eyebrow">${due.length} ${currentLang==='es'?'pendiente(s)':'pendente(s)'} · ${state.cards.length} ${currentLang==='es'?'en total':'no total'}</div><h3>${c.q}</h3><button class="btn secondary" id="reveal">${t('Revelar resposta')}</button><div id="back" style="display:none"><p><b>${c.a}</b></p><p>${c.why}</p><button class="btn" id="known">${t("Lembrei")}</button> <button class="btn secondary" id="again">${t("Rever amanhã")}</button></div>`;$('#reveal').onclick=()=>$('#back').style.display='block';$('#known').onclick=$('#again').onclick=e=>{if(e.target.id==='known'){c.level=Math.min((c.level||0)+1,4);c.due=Date.now()+[1,3,7,14,30][c.level-1]*86400000}else{c.level=0;c.due=Date.now()+86400000}save();renderReview()}}
function renderStats(){let rate=state.total?Math.round(state.correct/state.total*100)+'%':'—',due=state.cards.filter(c=>c.due<=Date.now()).length,pct=Math.round(state.done.length/8*100);['statQ','pQ'].forEach(id=>$(('#'+id)).textContent=state.total);$('#statRate').textContent=rate;$('#statDone').textContent=state.done.length+'/8';$('#statDue').textContent=due;$('#pRate').textContent=rate;$('#pDone').textContent=state.done.length+'/8';$('#progressBar').style.width=pct+'%';$('#pBar').style.width=pct+'%';$('#progressPct').textContent=pct+'%';$('#progressLabel').textContent=currentLang==='es'?state.done.length+' de 8 módulos':state.done.length+' de 8 módulos';$('#pText').textContent=`${state.correct} acertos em ${state.total} questões.`}
function resetProgress(){if(confirm(currentLang==='es'?'¿Borrar el progreso guardado en este dispositivo?':'Zerar o progresso salvo neste dispositivo?')){state={total:0,correct:0,done:[],cards:[]};save();renderReview()}}
window.resetProgress=resetProgress;
function val(id){return parseFloat($('#'+id).value)}
function out(id,s){$('#'+id).textContent=s}
window.calcIMC=()=>{let w=val('imcW'),h=val('imcH')/100;if(w>0&&h>0)out('imcOut',currentLang==='es'?`IMC: ${(w/(h*h)).toFixed(1)} kg/m². Interpretar según edad y contexto clínico.`:`IMC: ${(w/(h*h)).toFixed(1)} kg/m². Interpretar por idade e contexto clínico.`);else out('imcOut',currentLang==='es'?'Introduce valores válidos.':'Informe valores válidos.')};
window.calcSC=()=>{let w=val('scW'),h=val('scH');if(w>0&&h>0)out('scOut',`SC: ${Math.sqrt(w*h/3600).toFixed(3)} m² (Mosteller).`);else out('scOut',currentLang==='es'?'Introduce valores válidos.':'Informe valores válidos.')};
window.calcHS=()=>{let w=val('hsW');if(!(w>0)||w>150)return out('hsOut',currentLang==='es'?'Introduce un peso entre 0 y 150 kg.':'Informe um peso entre 0 e 150 kg.');let ml=w<=10?w*100:w<=20?1000+(w-10)*50:1500+(w-20)*20;let hourly=w<=10?w*4:w<=20?40+(w-10)*2:60+(w-20);out('hsOut',currentLang==='es'?`Estimación diaria: ${ml.toFixed(0)} mL/día. Estimación horaria por la regla 4/2/1: ${hourly.toFixed(1)} mL/h. Son aproximaciones y pueden diferir ligeramente. Evaluar indicación, fase clínica, balance y electrolitos.`:`Estimativa diária: ${ml.toFixed(0)} mL/dia. Estimativa horária pela regra 4/2/1: ${hourly.toFixed(1)} mL/h. Os métodos são aproximações e podem divergir levemente. Avaliar indicação, fase clínica, balanço e eletrólitos.`)};
window.calcGT=()=>{let v=val('gtV'),t=val('gtT'),f=val('gtF');if(v>0&&t>0)out('gtOut',currentLang==='es'?`${(v*f/(t*60)).toFixed(1)} gotas/min.`:`${(v*f/(t*60)).toFixed(1)} gotas/min.`);else out('gtOut',currentLang==='es'?'Introduce volumen y tiempo válidos.':'Informe volume e tempo válidos.')};
window.calcCG=()=>{let age=val('cgAge'),w=val('cgW'),cr=val('cgCr'),sex=$('#cgSex').value;if(age>0&&age<=120&&w>0&&w<=400&&cr>0){let r=((140-age)*w)/(72*cr)*(sex==='f'?.85:1);out('cgOut',currentLang==='es'?`Aclaramiento estimado: ${r.toFixed(1)} mL/min (Cockcroft–Gault). Resultado aproximado: la fórmula utiliza peso corporal y creatinina estable; la elección del peso requiere criterio, especialmente en obesidad, edema, bajo peso o amputaciones. No usar de forma aislada para ajustar dosis.`:`Clearance estimado: ${r.toFixed(1)} mL/min (Cockcroft–Gault). Resultado aproximado: a fórmula usa peso corporal e creatinina estável; escolha do peso exige julgamento, especialmente em obesidade, edema, baixo peso ou amputações. Não usar isoladamente para ajuste de dose.`)}else out('cgOut',currentLang==='es'?'Introduce edad, peso y creatinina válidos.':'Informe idade, peso e creatinina válidos.')};
window.calcConvert=()=>{let v=val('cvVal'),t=$('#cvType').value,f={'mg-g':.001,'g-mg':1000,'mcg-mg':.001,'mg-mcg':1000,'lb-kg':.45359237,'kg-lb':2.20462262}[t];out('cvOut',Number.isFinite(v)?(currentLang==='es'?`Resultado: ${(v*f).toPrecision(6)} (${t.replace('-',' → ')}).`:`Resultado: ${(v*f).toPrecision(6)} (${t.replace('-',' → ')}).`):(currentLang==='es'?'Introduce un valor.':'Informe um valor.'))};
function init(){renderModules();renderDrugs();renderAbx();renderProtocols();renderQ();renderCases();renderClinic();renderMock();renderStats();$('#languageSelect').value=currentLang;translateStatic()}
init();

