function updateIntroLanguage(lang){
 const c=introCopy[lang==='es'?'es':'pt'];
 Object.keys(c).forEach(k=>{const el=document.getElementById('intro'+k.charAt(0).toUpperCase()+k.slice(1));if(el){if(k==='title')el.innerHTML=c[k];else el.textContent=c[k];}});
}
function enterRmed(remember){
 document.body.classList.remove('landing');
 if(remember){try{localStorage.setItem('rmed_intro_seen','1')}catch(e){}}
 window.scrollTo(0,0);
}
const introLang=document.getElementById('introLanguage');
introLang.value=currentLang;
updateIntroLanguage(currentLang);
introLang.addEventListener('change',e=>{
 setLanguage(e.target.value);
 updateIntroLanguage(e.target.value);
 document.getElementById('languageSelect').value=e.target.value;
});
document.getElementById('enterRmed').addEventListener('click',()=>enterRmed(false));
document.getElementById('introRemember').addEventListener('click',()=>enterRmed(true));
try{if(localStorage.getItem('rmed_intro_seen')==='1')document.body.classList.remove('landing')}catch(e){}


